def choose_move(observation):
    # Basic deterministic: try to move toward nearest resource or toward center if none.
    x = observation.get("self_position", [0, 0])[0]
    y = observation.get("self_position", [0, 0])[1]
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    # helper to pick move toward target (tx, ty)
    def toward(tx, ty):
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        return [dx, dy]

    # 1) move toward nearest resource if available
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_dist = float("inf")
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            return toward(best[0], best[1])

    # 2) otherwise move toward opponent to contest
    opp = observation.get("opponent_position", None)
    if isinstance(opp, list) or isinstance(opp, tuple):
        ox, oy = opp[0], opp[1]
        return toward(ox, oy)

    # 3) otherwise head to center of grid
    if grid_w and grid_h:
        cx = grid_w // 2
        cy = grid_h // 2
        return toward(cx, cy)

    # 4) fallback stay still
    return [0, 0]
